    BaniLine(id = "ardas-9", gurmukhi = "ਤੇਗ ਬਹਾਦਰ ਸਿਮਰਿਐ ਘਰ ਨਉ ਨਿਧਿ ਆਵੈ ਧਾਇ ॥", transliteration = "teg bhaadar simriai ghar nau nidh aavai dhaai ||", translation = "Then I do remember Guru Tegh Bahadur, though whose Grace the nine treasures come running to my house.", hindi = "तेग बहादर सिमरिऐ घर नउ निधि आवै धाइ ॥", punjabi = "(ਗੁਰੂ) ਤੇਗ ਬਹਾਦਰ ਦੇ ਸਿਮਰਨ ਨਾਲ ਨੌ ਨਿੱਧਾਂ (ਖ਼ਜ਼ਾਨੇ) (ਘਰ ਵਿਚ) ਭਜਦੀਆਂ ਚਲੀਆਂ ਆਉਂਦੀਆਂ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-10", gurmukhi = "ਸਭ ਥਾਈਂ ਹੋਇ ਸਹਾਇ ॥੧॥", transliteration = "sabh thaaeen hoi shaai ||1||", translation = "May they be helpful to me everywhere.1.", hindi = "सभ थाईं होइ सहाइ ॥१॥", punjabi = "(ਸਾਰੇ ਗੁਰੂ ਮੈਨੂੰ) ਸਭ ਥਾਈਂ ਸਹਾਇਕ ਹੋਣ ॥੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-11", gurmukhi = "ਦਸਵਾਂ ਪਾਤਿਸ਼ਾਹ ਸ੍ਰੀ ਗੁਰੂ ਗੋਬਿੰਦ ਸਿੰਘ ਸਾਹਿਬ ਜੀ; ਸਭ ਥਾਈਂ ਹੋਇ ਸਹਾਇ ।", transliteration = "dasvaan paatishaah sree guroo gobind singh saahib jee; sabh thaaeen hoi shaai |", translation = "Then think of the tenth lord, revered Guru Gobind Singh, who comes to rescue everywhere.", hindi = "दसवां पातिशाह स्री गुरू गोबिंद सिंघ साहिब जी; सभ थाईं होइ सहाइ ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-12", gurmukhi = "ਦਸਾਂ ਪਾਤਿਸ਼ਾਹੀਆਂ ਦੀ ਜੋਤ ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਦੇ ਪਾਠ ਦੀਦਾਰ ਦਾ ਧਿਆਨ ਧਰ ਕੇ ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "dasaan paatishaaheeaan dee jot sree guroo granth saahib jee de paath deedaar daa dhiaan dhar ke bolo jee vaahiguroo |", translation = "The embodiment of the light of all ten sovereign lordships, the Guru Granth Sahib - think of the view and reading of it and say, \"Waheguru\".", hindi = "दसां पातिशाहीआं दी जोत स्री गुरू ग्रंथ साहिब जी दे पाठ दीदार दा धिआन धर के बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-13", gurmukhi = "ਪੰਜਾਂ ਪਿਆਰਿਆਂ, ਚੌਹਾਂ ਸਾਹਿਬਜ਼ਾਦਿਆਂ, ਚਾਲ੍ਹੀਆਂ ਮੁਕਤਿਆਂ, ਹਠੀਆਂ, ਜਪੀਆਂ, ਤਪੀਆਂ, ਜਿਹਨਾਂ ਨਾਮ ਜਪਿਆ, ਵੰਡ ਛਕਿਆ, ਦੇਗ ਚਲਾਈ, ਤੇਗ ਵਾਹੀ, ਦੇਖ ਕੇ ਅਣਡਿੱਤ ਕੀਤਾ, ਤਿਨ੍ਹਾਂ ਪਿਆਰਿਆਂ, ਸਚਿਆਰਿਆਂ ਦੀ ਕਮਾਈ ਦਾ ਧਿਆਨ ਧਰ ਕੇ, ਖ਼ਾਲਸਾ ਜੀ; ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "panjaan piaariaan, chauhaan saahibzaadiaan, chaalheeaan muktiaan, htheeaan, jpeeaan, tpeeaan, jihnaan naam jpiaa, vand chhkiaa, deg chlaaee, teg vaahee, dekh ke anditt keetaa, tinhaan piaariaan, schiaariaan dee kmaaee daa dhiaan dhar ke, khaalsaa jee; bolo jee vaahiguroo |", translation = "Meditating on the achievement of the dear and truthful ones, including the five beloved ones, the four sons of the tenth Guru, forty liberated ones, steadfast ones, constant repeaters of the Divine Name, those given to assiduous devotion, those who repeated the Naam, shared their fare with others, ran free kitchen, wielded the sword and ever looked faults and shortcomings, say \"Waheguru\", O Khalsa.", hindi = "पंजां पिआरिआं, चौहां साहिबज़ादिआं, चाल्हीआं मुकतिआं, हठीआं, जपीआं, तपीआं, जिहनां नाम जपिआ, वंड छकिआ, देग चलाई, तेग वाही, देख के अणडित्त कीता, तिन्हां पिआरिआं, सचिआरिआं दी कमाई दा धिआन धर के, ख़ालसा जी; बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-14", gurmukhi = "ਜਿਨ੍ਹਾਂ ਸਿੰਘਾਂ ਸਿੰਘਣੀਆਂ ਨੇ ਧਰਮ ਹੇਤ ਸੀਸ ਦਿੱਤੇ, ਬੰਦ ਬੰਦ ਕਟਾਏ, ਖੋਪਰੀਆਂ ਲੁਹਾਈਆਂ, ਚਰਖੜੀਆਂ ਤੇ ਚੜੇ, ਆਰਿਆਂ ਨਾਲ ਚਿਰਾਏ ਗਏ, ਗੁਰਦਵਾਰਿਆਂ ਦੀ ਸੇਵਾ ਲਈ ਕੁਰਬਾਨੀਆਂ ਕੀਤੀਆਂ, ਧਰਮ ਨਹੀਂ ਹਾਰਿਆ, ਸਿੱਖੀ ਕੇਸਾਂ ਸੁਆਸਾਂ ਨਾਲ ਨਿਬਾਹੀ, ਤਿਨ੍ਹਾਂ ਦੀ ਕਮਾਈ ਦਾ ਧਿਆਨ ਧਰ ਕੇ ਖ਼ਾਲਸਾ ਜੀ; ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "jinhaan singhaan singhneeaan ne dharam het sees ditte, band band ktaae, khopreeaan luhaaeeaan, charakhreeaan te chre, aariaan naal chiraae gae, guradvaariaan dee sevaa laee kurbaaneeaan keeteeaan, dharam nheen haariaa, sikkhee kesaan suaasaan naal nibaahee, tinhaan dee kmaaee daa dhiaan dhar ke khaalsaa jee; bolo jee vaahiguroo |", translation = "Meditating on the achievement of the male and female members of the Khalsa who laid down their lives in the cause of dharma (religion and righteousness), got their bodies dismembered bit by bit, got their skulls sawn off, got mounted on spiked wheels, got their bodies sawn, made sacrifices in the service of the shrines (gurdwaras), did not betray their faith, sustained their adherence to the Sikh faith with sacred unshorn hair up till their last breath, say, \"Waheguru\", O Khalsa.", hindi = "जिन्हां सिंघां सिंघणीआं ने धरम हेत सीस दित्ते, बंद बंद कटाए, खोपरीआं लुहाईआं, चरखड़ीआं ते चड़े, आरिआं नाल चिराए गए, गुरदवारिआं दी सेवा लई कुरबानीआं कीतीआं, धरम नहीं हारिआ, सिख्खी केसां सुआसां नाल निबाही, तिन्हां दी कमाई दा धिआन धर के ख़ालसा जी; बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-15", gurmukhi = "ਪੰਜਾਂ ਤਖ਼ਤਾਂ, ਸਰਬੱਤ ਗੁਰਦੁਆਰਿਆਂ ਦਾ ਧਿਆਨ ਧਰ ਕੇ ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "panjaan takhtaan, sarabtt gurduaariaan daa dhiaan dhar ke bolo jee vaahiguroo |", translation = "Thinking of the five thrones (seats of religious authority) and all gurdwaras, say, \"Waheguru\", O Khalsa.", hindi = "पंजां तख़तां, सरबत्त गुरदुआरिआं दा धिआन धर के बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-16", gurmukhi = "ਪ੍ਰਿਥਮੇ ਸਰਬੱਤ ਖ਼ਾਲਸਾ ਜੀ ਕੀ ਅਰਦਾਸ ਹੈ ਜੀ, ਸਰਬੱਤ ਖ਼ਾਲਸਾ ਜੀ ਕੋ ਵਾਹਿਗੁਰੂ, ਵਾਹਿਗੁਰੂ, ਵਾਹਿਗੁਰੂ ਚਿੱਤ ਆਵੇ, ਚਿੱਤ ਆਵਨ ਕਾ ਸਦਕਾ ਸਰਬ ਸੁਖ ਹੋਵੇ ।", transliteration = "prithme sarabtt khaalsaa jee kee ardaas hai jee, sarabtt khaalsaa jee ko vaahiguroo, vaahiguroo, vaahiguroo chitt aave, chitt aavan kaa sadkaa sarab sukh hove |", translation = "Now it is the prayer of the whole Khalsa. May the conscience of the whole Khalsa be informed by Waheguru, Waheguru, Waheguru and, in consequence of such remembrance, may total well-being obtain.", hindi = "प्रिथमे सरबत्त ख़ालसा जी की अरदास है जी, सरबत्त ख़ालसा जी को वाहिगुरू, वाहिगुरू, वाहिगुरू चित्त आवे, चित्त आवन का सदका सरब सुख होवे ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-17", gurmukhi = "ਜਹਾਂ ਜਹਾਂ ਖ਼ਾਲਸਾ ਜੀ ਸਾਹਿਬ, ਤਹਾਂ ਤਹਾਂ ਰਛਿਆਂ ਰਿਆਇਤ, ਦੇਗ ਤੇਗ ਫ਼ਤਹ, ਬਿਰਦ ਕੀ ਪੈਜ, ਪੰਥ ਕੀ ਜੀਤ, ਸ੍ਰੀ ਸਾਹਿਬ ਜੀ ਸਹਾਇ, ਖ਼ਾਲਸੇ ਜੀ ਕੇ ਬੋਲ ਬਾਲੇ, ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "jahaan jhaan khaalsaa jee saahib, thaan thaan rchhiaan riaait, deg teg fatah, birad kee paij, panth kee jeet, sree saahib jee shaai, khaalse jee ke bol baale, bolo jee vaahiguroo |", translation = "Wherever there are communities of the Khalsa, may there be Divine protection and grace, and ascendance of the supply of needs and of the holy sword, protection of the tradition of grace, victory to the Panth, the succor of the holy sword, and ascendance of the Khalsa. Say, O Khalsa, \"Waheguru\".", hindi = "जहां जहां ख़ालसा जी साहिब, तहां तहां रछिआं रिआइत, देग तेग फ़तह, बिरद की पैज, पंथ की जीत, स्री साहिब जी सहाइ, ख़ालसे जी के बोल बाले, बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-18", gurmukhi = "ਸਿੱਖਾਂ ਨੂੰ ਸਿੱਖੀ ਦਾਨ, ਕੇਸ ਦਾਨ, ਰਹਿਤ ਦਾਨ, ਬਿਬੇਕ ਦਾਨ, ਵਿਸਾਹ ਦਾਨ, ਭਰੋਸਾ ਦਾਨ, ਦਾਨਾਂ ਸਿਰ ਦਾਨ ਨਾਮ ਦਾਨ, ਸ੍ਰੀ ਅੰਮ੍ਰਿਤਸਰ ਜੀ ਦੇ ਇਸ਼ਨਾਨ, ਚੌਂਕੀਆ, ਝੰਡੇ, ਬੁੰਗੇ ਜੁਗੋ ਜੁਗ ਅਟੱਲ, ਧਰਮ ਕਾ ਜੈਕਾਰ, ਬੋਲੋ ਜੀ ਵਾਹਿਗੁਰੂ ।", transliteration = "sikkhaan noon sikkhee daan, kes daan, rhit daan, bibek daan, visaah daan, bhrosaa daan, daanaan sir daan naam daan, sree amritasar jee de ishnaan, chaunkeeaa, jhande, bunge jugo jug atll, dharam kaa jaikaar, bolo jee vaahiguroo |", translation = "Unto the Sikhs the gift of the Sikh faith, the gift of the untrimmed hair, the gift of the disciple of their faith, the gift of sense of discrimination, the gift of truest, the gift of confidence, above all, the gift of meditation on the Divine and bath in the Amritsar (holy tank at Amritsar). May hymns-singing missionary parties, the flags, the hostels, abide from age to age. May righteousness reign supreme. Say, \"Waheguru\".", hindi = "सिख्खां नूं सिख्खी दान, केस दान, रहित दान, बिबेक दान, विसाह दान, भरोसा दान, दानां सिर दान नाम दान, स्री अंम्रितसर जी दे इशनान, चौंकीआ, झंडे, बुंगे जुगो जुग अटल्ल, धरम का जैकार, बोलो जी वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-19", gurmukhi = "ਸਿੱਖਾਂ ਦਾ ਮਨ ਨੀਵਾਂ, ਮਤ ਉੱਚੀ, ਮਤ ਦਾ ਰਾਖਾ ਆਪਿ ਵਾਹਿਗੁਰੂ ।", transliteration = "sikkhaan daa man neevaan, mat ucchee, mat daa raakhaa aap vaahiguroo |", translation = "May the Khalsa be imbued with humility and high wisdom! May Waheguru guard its understanding!", hindi = "सिख्खां दा मन नीवां, मत उच्ची, मत दा राखा आपि वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-20", gurmukhi = "ਹੇ ਅਕਾਲ ਪੁਰਖ ਆਪਣੇ ਪੰਥ ਦੇ ਸਦਾ ਸਹਾਈ ਦਾਤਾਰ ਜੀਓ ।", transliteration = "he akaal purakh aapne panth de sdaa shaaee daataar jeeo |", translation = "O Immortal Being, eternal helper of Thy Panth, benevolent Lord,", hindi = "हे अकाल पुरख आपणे पंथ दे सदा सहाई दातार जीओ ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-21", gurmukhi = "ਸ੍ਰੀ ਨਨਕਾਣਾ ਸਾਹਿਬ ਤੇ ਹੋਰ ਗੁਰਦੁਆਰਿਆਂ ਗੁਰਧਾਮਾਂ ਦੇ, ਜਿਨ੍ਹਾਂ ਤੋਂ ਪੰਥ ਨੂੰ ਵਿਛੋੜਿਆ ਗਿਆ ਹੈ, ਖੁਲ੍ਹੇ ਦਰਸ਼ਨ ਦੀਦਾਰ ਤੇ ਸੇਵਾ ਸੰਭਾਲ ਦਾ ਦਾਨ ਖ਼ਾਲਸਾ ਜੀ ਨੂੰ ਬਖਸ਼ੋ ।", transliteration = "sree nankaanaa saahib te hor gurduaariaan gurdhaamaan de, jinhaan ton panth noon vichhoriaa giaa hai, khulhe darashan deedaar te sevaa sambhaal daa daan khaalsaa jee noon bakhsho |", translation = "Bestow on the Khalsa the beneficence of unobstructed visit to the free management of Nankana Sahib and other shrines and places of the Guru from which the Panth have been separated.", hindi = "स्री ननकाणा साहिब ते होर गुरदुआरिआं गुरधामां दे, जिन्हां तों पंथ नूं विछोड़िआ गिआ है, खुल्हे दरशन दीदार ते सेवा संभाल दा दान ख़ालसा जी नूं बखशो ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-22", gurmukhi = "ਹੇ ਨਿਮਾਣਿਆਂ ਦੇ ਮਾਣ, ਨਿਤਾਣਿਆਂ ਦੇ ਤਾਣ, ਨਿਓਟਿਆਂ ਦੀ ਓਟ, ਸੱਚੇ ਪਿਤਾ, ਵਾਹਿਗੁਰੂ ।", transliteration = "he nimaaniaan de maan, nitaaniaan de taan, niotiaan dee ot, scche pitaa, vaahiguroo |", translation = "O Thou, the honor of the humble, the strength of the weak, aid unto those who have none to rely on, True Father, Waheguru,", hindi = "हे निमाणिआं दे माण, निताणिआं दे ताण, निओटिआं दी ओट, सच्चे पिता, वाहिगुरू ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-23", gurmukhi = "ਆਪ ਦੇ ਹਜ਼ੂਰ ... ਦੀ ਅਰਦਾਸ ਹੈ ਜੀ ।", transliteration = "aap de hzoor ... dee ardaas hai jee |", translation = "We humbly render to you ...", hindi = "आप दे हज़ूर ... दी अरदास है जी ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-24", gurmukhi = "ਅੱਖਰ ਵਾਧਾ ਘਾਟਾ ਭੁੱਲ ਚੁੱਕ ਮਾਫ ਕਰਨੀ ।", transliteration = "akkhar vaadhaa ghaataa bhull chukk maaph karnee |", translation = "Pardon any impermissible accretions, omissions, errors, mistakes.", hindi = "अख्खर वाधा घाटा भुल्ल चुक्क माफ करनी ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-25", gurmukhi = "ਸਰਬੱਤ ਦੇ ਕਾਰਜ ਰਾਸ ਕਰਨੇ ।", transliteration = "sarabtt de kaaraj raas karne |", translation = "Fulfill the purposes of all.", hindi = "सरबत्त दे कारज रास करने ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-26", gurmukhi = "ਸੇਈ ਪਿਆਰੇ ਮੇਲ, ਜਿਨ੍ਹਾਂ ਮਿਲਿਆਂ ਤੇਰਾ ਨਾਮ ਚਿਤ ਆਵੇ ।", transliteration = "seee piaare mel, jinhaan miliaan teraa naam chit aave |", translation = "Grant us the association of those dear ones, on meeting whom one is reminded of Your Name.", hindi = "सेई पिआरे मेल, जिन्हां मिलिआं तेरा नाम चित आवे ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ardas-27", gurmukhi = "ਨਾਨਕ ਨਾਮ ਚੜ੍ਹਦੀ ਕਲਾ, ਤੇਰੇ ਭਾਣੇ ਸਰਬੱਤ ਦਾ ਭਲਾ ।", transliteration = "naanak naam charhadee klaa, tere bhaane sarabtt daa bhlaa |", translation = "O Nanak, may the Naam (Holy) be ever in ascendance! In Thy will may the good of all prevail!", hindi = "नानक नाम चड़्हदी कला, तेरे भाणे सरबत्त दा भला ।", punjabi = "", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)
